'use client';

// =============================================================================
// PlanBoard — adapter del board /plan para el super-admin (localStorage)
// =============================================================================
// PROYECTOS FINITOS (inicio/fin, deadline, descripción y RAZÓN de prioridad rica),
// escritos en criollo. Prioridad 1-100 DISTINTA por proyecto; tareas con score 1-100
// repartido en pirámide (no todo el mismo número). Una tarea puede vivir en varios
// proyectos (labels es una lista). Toda la UI vive en board/BoardShell.

import { useEffect, useState } from 'react';
import { BoardShell } from './board/BoardShell';
import { useBoard } from './board/useBoard';
import { type BoardTask, type Label, type Repo, type BoardUser, type Hist, prioFromScore, clampScore } from './board/types';

const K8 = 'mako_plan_v8', K_PROJS = 'mako_plan_projs_v6';
const SEED_TS = Date.parse('2026-07-13T12:00:00Z');

const P = (id: string, emoji: string, name: string, color: string, score: number, scoreRazon: string, detalle: string, deadline: string): Label =>
  ({ id, emoji, name, color, score, scoreRazon: scoreRazon || undefined, deadline: deadline || undefined, detalle, historial: [{ id: 'seedp' + id, ts: SEED_TS, actor: 'ia', text: 'Creó el proyecto' }] });

// ── Proyectos FINITOS (prioridad 1-100 distinta + razón comparada) ──
const PROJS_DEFAULT: Label[] = [
  P("tooluse-core-de", "🧠", "El cerebro que actúa: MaKo deja de opinar y empieza a hacer", "#D0504A", 98, "El norte absoluto: es el cimiento de todo lo accionable. Sin que MaKo lea el negocio y proponga jugadas, no hay Retro que reclame, ni semáforo que accione, ni CRM que se explique. Todo lo demás cuelga de esto — por eso va primero.", "Hoy MaKo responde a ciegas: te da opiniones sin haber mirado un solo dato del negocio. Este proyecto lo convierte en un asistente que primero LEE (consulta tus leads, chats, reuniones y experimentos antes de contestar), después PROPONE (arma borradores que vos aprobás con un botón, nunca manda nada solo) y aparece metido dentro de cada pantalla. Sin esto no hay Retro que te reclame, ni semáforo que accione, ni CRM que se explique. Está listo cuando MaKo ve tus números de verdad y te propone la jugada concreta ahí donde estás parado.", "2026-08-31"),
  P("golive-encender-el", "🚀", "Prender el producto para el primer cliente real", "#2F6FED", 95, "Segundo porque hoy TODO corre en simulación: el motor está construido pero nada sale de verdad. Prenderlo, con cuidado, para el primer cliente real es lo que convierte \"hay código\" en \"el producto factura\". Sin esto, todo lo demás es potencial sin caja.", "El salto de 'está el código' a 'el producto actúa': hoy todo corre en simulación y nada sale de verdad. Este proyecto prende, de a uno y con cuidado, lo que ya está construido pero apagado (nutrición, email, WhatsApp oficial y no oficial, CRM automático), cliente por cliente, sin molestar a los demás ni perder datos de Meta que no se recuperan. Está listo cuando un cliente piloto corre con envío real encendido, dominio de email verificado, WhatsApp conectado y una plantilla aprobada por Meta en vivo.", "2026-07-31"),
  P("cerrar-la-auditora", "🛡️", "Cerrar la auditoría de seguridad antes de traer clientes", "#0E9B8E", 92, "Va antes de traer clientes reales: quedan fugas que dejan ver datos de un cliente a otro. Es un bloqueo de seguridad, no un nice-to-have — un leak con gente pagando te funde la reputación. Los graves ya están tapados; falta la cola.", "Llevar a cero los agujeros de seguridad antes de onboardear clientes reales. El problema de fondo: hay consultas que van a la base sin filtrar por cliente, y eso filtra datos de un cliente a otro. Está cerrado cuando no queda ni una fuga entre cuentas, las acciones de configuración quedaron aplicadas en producción, y las protecciones del navegador y los webhooks están endurecidas. Los agujeros graves ya están tapados; falta la cola larga.", "2026-07-25"),
  P("crm-automtico-leads", "🤖", "CRM automático: leads que avanzan solos", "#7C5CFB", 88, "El corazón del doer y ya casi listo (las 6 reglas corren en simulación). Mueve leads solos con criterio de closer; encenderlo multiplica el valor sin trabajo nuevo. Debajo de go-live porque depende de que el envío real esté prendido primero.", "MaKo mueve el lead de etapa con el criterio de un buen closer: agenda una reunión y tres horas después chequea si el tipo asistió, deriva a nutrición al que no agenda, marca el no-show, reactiva al que se enfrió. Son seis reglas que nunca pisan un dato que cargaste vos, dejan rastro con autor 'MaKo' y siempre aplican-y-después-piden-tu-OK con un aviso que no se puede ignorar. El motor entero ya está en producción, pero en simulación. Está listo cuando se prende por cliente y mueve leads reales sin quemar pólvora.", "2026-08-20"),
  P("recordatorios-de-juntas", "⏰", "Recordatorios de reuniones y follow-ups (chau n8n)", "#C8870C", 85, "El no-show es el asesino nº1 del high-ticket y hoy la nutrición casi no corre. Reconstruir recordatorios y follow-ups DENTRO de la app (sacándolos de n8n) es plata que hoy se pierde sola. Impacto directo en cierres.", "Traer DENTRO de la app todo el seguimiento que hoy vive en n8n, sobre otra base de datos y apagado: recordatorios de reunión (24h, 1h, 15 min), la tanda de follow-ups, la cobranza de cuotas vencidas y el mensaje post-llamada. El no-show es el asesino número uno del high-ticket y hoy la nutrición casi no corre. Además ataca el problema de tener dos bases que no se hablan y a Calendly procesado por las dos. Está listo cuando la app manda recordatorios y follow-ups sola y podemos apagar n8n.", "2026-08-20"),
  P("multiinquilino-workspace", "🏢", "Cada cliente en su propia cuenta, aislado del resto", "#D6489B", 80, "El piso para venderle a más de un cliente sin filtrar datos ajenos. Casi todo hecho; queda plomería. Alto porque nada del negocio escala sin esto, pero está maduro, así que no urge tanto como lo de arriba.", "Pasar el dashboard de 'una sola cuenta donde todos veían los datos de Mauricio' a multi-cliente: cada usuario tiene su cuenta aislada, hay un panel de agencia para 'entrar como' cualquier cliente, y cada uno corre con SUS credenciales y SU ingesta. Sin esto no se puede vender MaKo a un segundo cliente sin filtrarle datos ajenos. El núcleo está entregado y andando en producción.", ""),
  P("retro-real-rendicin", "🔎", "Retro real: que MaKo te rinda cuentas", "#1E9E57", 78, "El cerebro que mira todo el negocio y te rinde cuentas. Hoy la rendición es de mentira (chequea si tocaste \"Aceptar\", no si lo hiciste). Cerrarla es lo que hace a MaKo un socio que reclama, no un tablero que mira.", "La Retro es el único cerebro que mira TODO el negocio: lee por áreas, te da veredictos, propone experimentos y tareas, y cuando aceptás los crea de verdad. El problema: la rendición de cuentas hoy es de mentira. MaKo chequea si tocaste 'Aceptar', no si realmente lo hiciste. Este proyecto cierra el círculo: que detecte fugas con criterio, verifique lo que EJECUTASTE contra lo que prometiste, te lo reclame y no te vuelva a proponer lo que ya ignoraste. Terminado cuando la Retro deja de ser un informe caro que pedís cuando querés y pasa a ser un coach que te persigue.", "2026-08-25"),
  P("pulso-diario-vista", "💓", "Pulso diario: la vista Hoy + un semáforo que piensa", "#98A0AC", 74, "El \"qué hacer hoy\" — el latido que te reclama por campanita y WhatsApp. Altísimo valor de doer, pero cuelga del tool-use core y de la Retro para tener de qué reclamar; por eso va después de ellos.", "Lo que a todos los pilares del producto les falta por igual: un LATIDO barato y periódico que lee qué se hizo de verdad, razona liviano y te reclama o te avisa por campanita y WhatsApp. En vez de un dashboard que abruma, una vista 'Hoy' con las 3 jugadas que más plata mueven, un semáforo que ya no solo linkea sino que razona alertas nuevas, y una bandeja de propuestas que aparece cuando NO estás mirando el chat (sin pop-ups que te bloqueen para lo no urgente). Terminado cuando abrís MaKo a la mañana y sabés exactamente qué hacer, y si no lo hacés, te lo reclama.", "2026-09-20"),
  P("funnel-como-fuente", "🧭", "El funnel como única fuente de verdad", "#D0504A", 70, "Alimenta métricas, nutrición y automatizaciones. Si el funnel no es la fuente de verdad, todo lo de arriba asume un embudo fijo de 2 reuniones y se rompe con clientes que tienen otro proceso. Transversal y habilitante.", "Que la definición de tu proceso comercial (etapas, transiciones, bandas, disparadores) sea lo que TODO lo demás consume, en vez de una pantalla suelta. El editor, la derivación automática y el rediseño conceptual ya existen; el norte es que MaKo, las métricas, los SLAs, la línea de tiempo y la nutrición dejen de tener las etapas clavadas en el código y lean el funnel. Terminado cuando agregar una etapa en /funnel se refleja solo en tableros, reglas y contexto de la IA, sin tocar una línea de código.", "2026-08-30"),
  P("ficha-del-lead", "🪪", "La ficha del lead: toda la historia en una sola pantalla", "#2F6FED", 66, "El CRM donde vive cada lead — ya está al 90%+ tras el rediseño de 15 puntos. Valor altísimo y casi entregado; queda pulir deuda (funnel fijo en la timeline). Por eso importa pero no es un frente caliente.", "El rediseño completo del detalle del lead: un asistente que mueve el lead de etapa preguntando de a un paso, pestañas ordenadas (resumen, tracking, reuniones, datos del trato, historial), cuotas claras, el contrato leído por IA, tracking fino por persona, una pestaña de chat y análisis generado por MaKo. Se fusionó todo en una ficha ÚNICA, editable con un gesto. Está listo cuando abrir un lead te cuenta toda su historia en una sola vista y MaKo te redacta lo que falta. Casi todo entregado; quedan colas de deuda técnica.", ""),
  P("motor-de-nutricin", "🤖", "Motor de nutrición multicanal + plantillas de Meta", "#0E9B8E", 62, "El brazo ejecutor de todo el seguimiento: construido y anti-baneo, pero apagado. Su valor real se desbloquea con el go-live; hasta entonces es un motor listo esperando la llave.", "El cerebro que decide y dispara la nutrición del lead según su etapa, con reglas para no comerse un baneo (demora al escribir proporcional, pausas al azar, tope de envíos) sobre WhatsApp y Email compartiendo la misma cohorte y un candado de 20h por lead. Más todo el circuito para redactar, validar y publicar plantillas de mensaje en Meta. Importa porque convierte el funnel en acción sin manos, y sin plantillas aprobadas no hay forma de reabrir la ventana de 24h. Motor y plantillas están completos en código; hoy corren en simulado (el encendido real se trata en el go-live).", ""),
  P("bandejas-de-whatsapp", "📥", "Bandejas de WhatsApp (oficial + no oficial por QR)", "#7C5CFB", 58, "Donde el equipo conversa con los leads (oficial Chatwoot + no oficial Evolution). Mayormente construido; el canal importa mucho, pero el cuello ahora es encenderlo (go-live), no construir más bandeja.", "El inbox de WhatsApp fiel a la app nativa, sobre DOS canales: el oficial (la API de Meta vía Chatwoot, para el tráfico frío de los ads) y el no oficial por QR (el número real de venta del cliente, sin las restricciones de la API oficial). Leer y responder, multimedia, notas de voz, borradores, avisos en vivo, la ficha del lead a un clic y paridad total entre los dos canales. Importa porque es donde el equipo conversa con los leads. Los dos canales están enviados; quedan las piezas de cierre y el arranque asistido.", "2026-08-25"),
  P("mako-escribe-la", "🖋️", "MaKo escribe la nutrición (y aprende tu voz)", "#C8870C", 54, "Que MaKo redacte la nutrición en la voz del cliente y arme el copy — lo que saca la fricción de escribir 30 mensajes a mano. Fuerte diferenciador, pero cuelga del tool-use core y del motor de nutrición prendido.", "Que el cliente no tenga que redactar 30 mensajes a mano. MaKo aprende cómo habla el negocio (mirando sus anuncios y su marca), escribe cada mensaje de la secuencia en esa voz, y el cliente solo revisa y aprueba. La misma máquina escribe también el copy de los anuncios y, más adelante, guiones de VSL y DMs. Multiplica el criterio de Martín a escala. F3 y el estudio de copy están hechos; falta encender el envío real y sumar los escritores de VSL/DM.", "2026-09-30"),
  P("arranque-del-cliente", "🧳", "Arranque del cliente: onboarding sin fricción", "#D6489B", 50, "El onboarding y el Modo Simple: la primera impresión que define si el cliente entiende MaKo o se abruma. Importa para escalar la captación de clientes, pero después de que el producto haga cosas de verdad.", "Que un cliente nuevo sea productivo con la menor fricción posible: un wizard que lo lleva de la mano por conectar integraciones, extraer su histórico, configurar tabs, cargar su negocio y correr la primera Retro; una vista SIMPLE por default (3 tareas + experimentos) con el kanban completo detrás de un toggle Avanzado; y el principio de pedir la MENOR config manual (primero defaults, después plantillas y sugerencias, y recién al final el editor a mano). Terminado cuando un cliente pasa el arranque solo, su histórico se extrae aunque cierre la pestaña, y ninguna pantalla lo obliga a 'armar' el sistema.", "2026-08-31"),
  P("cerrar-el-ciclo", "🎯", "Cerrar el ciclo con Meta: nueva campaña, salud y Purchase", "#1E9E57", 47, "Las piezas que faltan para manejar Meta de punta a punta: nueva campaña, salud de cuenta y el evento Purchase por CAPI (que le enseña a Meta a traer compradores, no solo leads). Alto retorno, pero depende de que las escrituras a Meta ya andan.", "Las tres piezas que faltan para manejar Meta de punta a punta sin salir de MaKo: lanzar campañas nuevas (describís la idea, subís los creativos y MaKo arma la estructura, la editás y sale en pausa), una vista que te dice si la cuenta está entregando bien y qué tocar, y avisarle a Meta cuándo cobraste de verdad para que optimice sobre la plata que entra y no solo sobre las agendas. Listo cuando publicás una campaña completa, la salud te sugiere sola y Meta aprende del cash cobrado.", "2026-08-15"),
  P("rplica-de-meta", "📋", "Ads Manager propio + escribir de vuelta a Meta", "#98A0AC", 44, "El Ads Manager dentro de MaKo con escritura a Meta — ya funciona (renombrar, editar, crear en pausa). Muy entregado; queda confirmar el CREATE en vivo. Baja en la lista porque el grueso está hecho.", "Un Ads Manager dentro de MaKo: navegar campañas, conjuntos y anuncios como en Meta y ESCRIBIR de vuelta (pausar/activar, presupuesto, renombrar en lote con nomenclatura, editar público/anuncio/conjunto) sin salir de la app. Cierra el loop ver→decidir→accionar que un dashboard de solo lectura no da. Entregado y probado con 27 campañas reales: cada cambio llega a Meta con manejo de error de verdad (Meta a veces responde OK con un error adentro), habilitado solo para el dueño, y el renombrado en lote aplica una nomenclatura jerárquica consistente.", ""),
  P("sistema-de-contexto", "🧩", "El contexto que hace que MaKo deje de responder genérico", "#D0504A", 42, "El cerebro de conocimiento (RAG + prompts + fases + cursos) que le da criterio a MaKo. Mayormente hecho y load-bearing para los analistas y writers, pero es infra silenciosa más que un frente nuevo.", "El cimiento que le da a MaKo criterio propio del negocio: cada vez que responde arma su contexto sumando quién es + metodología + el perfil del cliente + una instrucción según la pantalla + el conocimiento que recupera (de cursos y áreas) + los datos del gráfico, y descarta lo que falle sin romperse. Además, todos los prompts del producto (33) se editan desde una pantalla, sin tocar código ni redeployar. Construido al ~90%; falta enchufarle los números vivos, registrar los prompts que quedaron sueltos y mejorar la búsqueda a escala.", "2026-08-15"),
  P("experimentos-como-fuente", "🧪", "Experimentos: el único lugar donde MaKo concluye con datos", "#2F6FED", 40, "La única vista que concluye con datos (hipótesis → experimento → veredicto), con la regla \"MaKo sugiere, no concluye\". Ya en prod; queda el auto-cierre. Importante como disciplina, pero no urgente.", "Acá una hipótesis se vuelve un experimento medible: con línea de base, medición automática y veredicto al cerrar. Es a propósito el único lugar donde MaKo afirma; en el resto sugiere abrir un experimento, nunca concluye, y solo las verdades ya validadas entran a su contexto. El ciclo, la medición y las tres vistas ya están; falta el combustible (plata cobrada por anuncio, histórico de veredictos) y automatizar el cierre. Se ve terminado cuando los experimentos se cierran solos y las decisiones se apoyan en cash real por creativo.", "2026-09-30"),
  P("closing-analyst-analista", "📞", "Closing Analyst — el analista de tus llamadas de venta", "#0E9B8E", 38, "El analista de llamadas de venta — entregado y funcionando sobre Fathom. Valor probado; queda como base para el CS Analyst y el copiloto. Bajo porque ya está hecho.", "Trae las llamadas grabadas en Fathom, las matchea con cada lead por email, separa las de VENTA (R1/R2) de las de entrega de servicio (coaching a clientes ya cerrados) y corre Claude para puntuar la ejecución, marcar momentos clave, objeciones y el próximo paso. Importa porque se graba todo y solo una fracción son ventas reales: sin ese árbitro, las sesiones de servicio ensuciaban el análisis y hasta los R1/R2 del lead. Ya entregado: dos vistas (Métricas y Llamadas con la grabación embebida), puntaje robusto y R1/R2 re-vinculados solo con ventas.", ""),
  P("comunicacin-con-el", "🔔", "Comunicación con el dueño + señales de WhatsApp", "#7C5CFB", 36, "Cómo MaKo te habla a VOS (reportes, campanita, WhatsApp) + las señales del lead. La base está; lo pendiente es multi-cliente y las señales finas. Habilita el doer proactivo, pero es soporte.", "Que el dueño reciba lo urgente y los resúmenes por donde prefiera (WhatsApp, email o Telegram), pueda responder ahí mismo y que MaKo ejecute lo que le pide ('sí, dale' → pausar campañas), y que el CRM 'sienta' lo que pasa en WhatsApp: última respuesta, contactos, con qué número se habló. Importa porque convierte los reportes en acción sin abrir la app y destraba el seguimiento automático del que no contesta. El perfil, la campanita y los reportes al dueño ya están; falta que los reportes salgan por cada cliente, que MaKo actúe sobre lo que le respondés, y las señales finas por lead.", "2026-08-30"),
  P("cuentas-roles-y", "🔑", "Cuentas, roles y equipo", "#C8870C", 34, "Cuentas, roles y equipo (closer/setter por workspace) — entregado. Necesario para el multi-usuario, pero ya resuelto, así que no compite por foco.", "Reemplazar la contraseña compartida por cuentas reales con rol, sesión firmada, un flujo para cargar los tokens de cada integración, y roles de negocio por cliente (admin-cliente, closer, setter) con el control real del lado del servidor. Importa porque la contraseña única no distinguía a la agencia del cliente ni podía suspender a nadie, y un closer no tiene por qué ver la facturación. Terminado cuando cada persona entra con su cuenta de Google, el sistema valida contra la base en cada pedido, los tokens se cargan cifrados con tutorial, y dar de alta a un cliente crea su workspace y su admin en un solo paso. Ya está en prod.", ""),
  P("dashboard-de-analtica", "📊", "Tablero de analítica de marketing (el núcleo de reporte)", "#D6489B", 32, "El producto original: el tablero que convierte todo en decisiones. Es el cimiento sobre el que MaKo razona y está entregado de punta a punta — por eso, a pesar de ser la base, hoy pide menos foco que lo que falta construir encima.", "El producto original y el cimiento de todo lo demás: el tablero que convierte Meta, Calendly, el VSL y los pagos en pantallas para decidir. Vista General ('tu norte' con objetivo, ritmo y fecha estimada de llegada), Marketing (CAC en tres niveles, ROAS, anuncios ganadores con veredicto), Comercial (cohortes, ciclo de venta, no-show) y Plata/Cobranza (vendido/cobrado/por cobrar, plan de cuotas, contrato leído por IA, a quién cobrarle). Es la capa de números confiables sobre la que MaKo razona: sin esto no hay doer ni semáforo ni Retro. Entregado de punta a punta.", ""),
  P("cimientos-de-datos", "🔌", "Cimientos de datos: conectores e ingesta de todas las fuentes", "#1E9E57", 30, "La cañería que alimenta todo (conectores Meta/Calendly/VSL/CAPI). Entregado; sin esto nada tiene datos, pero justamente por estar hecho ya no es un frente. Queda algo de multi-cliente que vive en otros proyectos.", "La cañería que alimenta todo el resto: los conectores a Meta Ads (rendimiento por anuncio + presupuestos), Meta Lead Ads (formularios que entran solos, cruzados por teléfono), Calendly (agendas que entran solas + histórico), el VSL (YouTube y Panda) y los eventos de conversión de vuelta a Meta (CAPI). Sin ingesta confiable e histórico cargado, ninguna vista ni MaKo tiene con qué razonar. Cada fuente quedó con su webhook, su repaso diario de seguridad y su carga histórica corrida. Entregado.", ""),
  P("script-analyst-analista", "🎬", "Script Analyst — el analista de tus guiones de video ads", "#98A0AC", 28, "El analista de guiones de video ads — entregado. Valioso para mejorar creativos, pero ya está y no bloquea nada urgente.", "Cruza la lectura de Claude sobre el guion (ángulo, hook, formato, estructura, diagnóstico) con la retención real de Meta por tramos y las agendas/cierres del CRM. La clave es separar lo que envejece (las métricas vivas, nunca congeladas) de lo estable (la lectura del guion, una por anuncio), así un guion se juzga por su desempeño ACUMULADO. Ya entregado (55 guiones): Patrones, un cuadrante de retención calibrado, un valorador de guiones nuevos, taxonomía editable de ángulos/avatares e imágenes leídas por OCR. Solo queda limpiar código muerto y un tablero alternativo.", "2026-07-25"),
  P("board-plan-perro", "🐕", "Board /plan — el Perro Guardián que prioriza", "#D0504A", 26, "Este mismo tablero de ejecución con el Perro Guardián. Ya es la herramienta de planificación; lo pendiente es deuda propia (sacar flags temporales, persistir metadata del cliente). Meta-trabajo, no aguja del negocio.", "El tablero donde se planifica y prioriza TODO el roadmap: un Trello propio (renombrado /plan) con los proyectos como pieza de primera clase, columnas de prioridad, checklists que calculan el avance, historial de cambios y un mismo componente para agencia y cliente. Encima, un 'Perro Guardián' (MaKo) que prioriza al crear una tarea, la debate, cuida que el backlog sea una pirámide sana y ordena los proyectos del 1 al 10 sin empates. Entregado y poblado con el roadmap sacado de la memoria; solo quedan cierres de desarrollo.", ""),
  P("reskin-de-la", "🎨", "Reskin de la app + identidad MaKo", "#2F6FED", 22, "El rediseño y el branding MaKo — transversal y continuo. Hace todo más usable y vendible, pero acompaña al resto en vez de competir por el primer lugar.", "Dejar toda la app con un mismo look, prolijo y alineado a la landing, pantalla por pantalla (el tablero de marketing, el funnel, los analistas, la Retro), con el sidebar plegable por grupos, la identidad de MaKo (logo, voz rioplatense, cada gráfico con su análisis de IA al lado) y los textos migrados a R1/R2. Importa porque una app despareja se siente a medio hacer y frena que la usen; es transversal y nunca termina del todo. Listo cuando no quede ninguna pantalla con el estilo viejo ni ningún gráfico sin su ✦ de MaKo. Mayormente hecho.", "2026-09-30"),
  P("landing-de-venta", "🌐", "Landing /vsl + páginas de detalle + atribución del VSL", "#0E9B8E", 18, "La cara comercial (/vsl). Importa para vender MaKo hacia afuera, pero recién cuando el producto esté DOER de verdad — vender algo a medio hacer quema pólvora.", "La cara pública de venta de MaKo: la landing con el VSL en el hero y un CTA que agenda por Calendly, las 15 páginas de detalle por funcionalidad, y la cadena que convierte a un espectador anónimo del VSL en un lead identificado con todo su comportamiento. Importa porque es cómo se vende el producto y cómo se mide el tráfico. El grueso de la landing y el motor de atribución ya están arriba; el cuello real es que Martín pegue el código de seguimiento en la landing y arme el flujo de WhatsApp, más completar los espacios en blanco de las páginas de detalle.", "2026-08-15"),
  P("skills-de-claude", "🛠️", "Skills de Claude Code + mapa del código + gasto de IA", "#7C5CFB", 16, "Las skills de Claude Code + Graphify + el gasto de IA: aceleran MI trabajo de construir MaKo. Palanca de velocidad de desarrollo, no del negocio del cliente; por eso va bajo.", "Las herramientas de construcción y de medición que hacen a MaKo un producto barato de armar y con las cuentas claras: recetas a medida del repo que evitan errores repetidos (más algunas públicas seleccionadas), un mapa navegable del código para no perderse, y el registro de cuánto cuesta cada operación de IA contra un saldo cargado a mano. Importa porque acelera el desarrollo y da transparencia del costo de cada funcionalidad. Ya está todo armado y subido; lo que queda es usar las recetas como hábito.", ""),
  P("agente-de-ads", "📈", "Agente de Ads: MaKo optimiza el gasto solo (con tu OK)", "#C8870C", 14, "Que MaKo optimice el gasto solo (con tu OK). Palanca de ROI enorme, pero depende del tool-use core y de la atribución de cash — es un futuro cercano, no un ahora.", "Cerrar el círculo entre lo que gastás y la plata que entra de verdad: que MaKo proponga (y con tu OK ejecute) subirle presupuesto a los anuncios que venden, apagar los que queman plata y duplicar ganadores, usando la plata cobrada por anuncio como brújula en lugar de solo la cantidad de leads. Es la palanca de retorno más directa ahora que ya podemos escribir en Meta y el tool-use está vivo. Terminado = reglas de subir/apagar propuestas con datos, ejecución en un clic con rastro, y el histórico de veredictos guardado para detectar cuándo un anuncio lleva días quemando. Las piezas están listas; falta el agente que las orquesta.", "2026-10-01"),
  P("cs-analyst-analista", "🩺", "CS Analyst: analista de retención (anticipar bajas)", "#D6489B", 12, "El analista de retención/churn sobre las llamadas de entrega. La función nueva más barata (reusa el Closing), pero es post-venta: entra cuando ya haya cartera que cuidar.", "El gemelo del Closing Analyst pero sobre las llamadas de ENTREGA del servicio, que hoy se transcriben y se tiran a la basura. Es la función nueva más rentable y barata porque reusa toda la infra del Closing y le suma un termómetro de baja por cliente: cruza el ánimo de la última llamada con la cuota impaga y otras señales para ver quién se va a ir antes de que se vaya. Terminado = llamadas de servicio analizadas con resumen, riesgos y próximos pasos, un termómetro por cliente y alertas de baja que le llegan al dueño. Sin arrancar; los datos ya existen, solo se descartan.", "2026-09-15"),
  P("growth-vender-mako", "📣", "Growth — vender MaKo hacia afuera", "#1E9E57", 9, "Vender MaKo hacia afuera (planes, ads por feature, testimonios). Marketing del producto, no producto: importa para crecer, pero después de tener algo terminado que mostrar.", "El marketing del producto (no el producto en sí): venderle MaKo a cualquiera que corra un VSL Funnel. Incluye la oferta por niveles que desbloquea según la situación del cliente, muchos anuncios donde cada uno vende una sola funcionalidad (modelo Claudio Conde), testimonios, la página de gracias post-agenda, demos por funcionalidad y un mapa de uso. Importa para crecer, pero va a propósito DESPUÉS de que el producto haga las cosas de verdad: vender algo a medio hacer quema pólvora y reputación. Por eso casi todo es a futuro y de prioridad baja.", ""),
  P("infraestructura-propia-e", "🧰", "Infraestructura propia + escala de mensajería", "#98A0AC", 7, "Pasar cuentas a nombre propio + escalar la infra de mensajería. Solo urge cuando haya clientes pagando y volumen; hoy es lejano.", "El trabajo de fondo que hace a MaKo independiente de la agencia y listo para muchos clientes: pasar la base de datos, el hosting y el dominio a nombre propio (con la landing en la raíz, no en /vsl), un método para actualizar sin cortarle a los que están probando, y cuentas propias por cliente para email y WhatsApp no oficial (hoy usan una única cuenta de MaKo que se topa con los límites de envío al escalar). Importa a mediano plazo pero hoy nada lo frena. Listo cuando MaKo corre en infra propia, con actualizaciones ordenadas, y cada cliente con volumen usa su propia cuenta. Muy a futuro.", ""),
  P("canales-fros-bot", "🧊", "Canales fríos: bot que contiene + entrada por IG y mail", "#D0504A", 4, "Bot de contención para tráfico frío + inbound-first + Instagram. De arranque lejano: depende de que todo el resto ya funcione solo. Puro \"a futuro\".", "Sumar los canales de entrada fríos sin quemar los números de venta. Un bot en la línea oficial que recibe el tráfico frío de los ads, lo contiene y recién ahí lo pasa al número de venta ya tibio; más el patrón de que el lead escriba primero (link con palabra clave + QR en vivo), que baja muchísimo el riesgo de que nos bloqueen la línea. Suma también los DMs de Instagram y un buzón de mail por lead a la bandeja única. Es de arranque lejano y depende de que el resto ya funcione solo; hoy está todo sin empezar.", ""),
  P("copiloto-en-vivo", "🎧", "Copiloto en vivo de la llamada", "#2F6FED", 2, "El moonshot: copiloto en vivo de la llamada con transcripción en tiempo real. Diferenciador máximo, pero es lo único que choca con algo que hoy no existe en el stack. Lo más lejano de todo.", "El sueño grande: un copiloto que escucha la llamada de venta en tiempo real y le va sugiriendo al closer respuestas y manejo de objeciones mientras habla, alimentado por el cerebro de copywriting y closing que ya tenemos curado. Es el diferenciador máximo del producto, pero es lo único de todo el plan que choca con algo que hoy no existe en el stack: transcripción en vivo. Terminado = la llamada transcripta en vivo + sugerencias al instante durante la reunión. Es una idea, sin arrancar; queda lejos por dificultad y costo.", ""),
];

// [num, title, projectIds[], score(1-100), prog, detalle, enPrioridad] — score DISTINTO por tarea
type Row = [number, string, string[], number, number, string, boolean];
const SEED: Row[] = [
  [1, "MaKo ya lee el negocio (6 fuentes conectadas)", ["tooluse-core-de"], 98, 100, "MaKo dejó de estar mudo: ahora puede consultar tus leads, la ficha de cada uno, el historial de WhatsApp, las reuniones, tu base de conocimiento y el estado de los experimentos, siempre acotado a tu propia cuenta. Tiene su pantalla propia y ya medimos cuánto cuesta cada consulta en IA.", false],
  [2, "Que MaKo hable con tus números reales, no de memoria", ["tooluse-core-de", "funnel-como-fuente"], 96, 25, "Cuando charlás con MaKo hoy, opina sin ver el estado real del funnel. La pieza clave: meterle un resumen vivo de tu embudo y tus métricas al arranque de cada conversación, para que cite números de verdad antes de responder. Es lo más fácil de hacer y lo que más mueve la aguja.", false],
  [3, "Que MaKo proponga jugadas y vos las aprobés con un botón", ["tooluse-core-de", "mako-escribe-la"], 95, 0, "Elegiste el camino 'leer y proponer, nunca mandar solo'. MaKo arma el borrador (un WhatsApp, una campaña en PAUSA, una secuencia de nutrición) y vos lo aprobás inline, sin sorpresas. Todo lo que sale de verdad pasa siempre por el filtro de permiso y confirmación: nada se dispara por atrás.", false],
  [4, "Prender los distintos MaKo y meterlos en cada pantalla", ["tooluse-core-de", "ficha-del-lead", "experimentos-como-fuente"], 93, 20, "El 'multi-agente' que promete la landing hoy es un solo MaKo: los modos Analista, Comparador y Closer están escritos pero apagados. Hay que rutear cada pedido al modo que corresponde y llevar el MaKo con números vivos a funnel, ficha del lead, experimentos, email y closing. Hoy solo WhatsApp lo tiene embebido.", false],
  [5, "El interruptor de envío tiene que ser por cliente, no global", ["golive-encender-el", "motor-de-nutricin", "crm-automtico-leads"], 91, 33, "Hoy los envíos de nutrición, email y CRM automático se prenden para TODOS los clientes de una: encender uno le mueve y contacta leads a cualquiera, y quema pasos como si fueran de mentira. Hay que poder prenderlos cliente por cliente para hacer un piloto seguro. El email ya funciona así; falta pasar nutrición y CRM automático al mismo esquema.", false],
  [6, "Salvar los datos de Meta antes de que los borre (URGENTE)", ["golive-encender-el", "cimientos-de-datos"], 90, 0, "Meta borra las respuestas de los formularios de leads a los 90 días y no se recuperan. Además, el anuncio y la campaña de origen de cada lead nunca se están guardando. Hay que empezar a guardar todo eso en la ingesta y rescatar lo que todavía esté dentro de la ventana. Corre contra reloj, entre o no el primer cliente.", false],
  [7, "Conectar WhatsApp no oficial, email y la primera plantilla en vivo", ["golive-encender-el", "bandejas-de-whatsapp", "motor-de-nutricin"], 88, 0, "Conectar el WhatsApp no oficial por QR usando un chip descartable (nunca el personal) y verificar que el espejo del chat quedó vivo de verdad (puede decir 'conectado' y estar muerto en silencio). Verificar el dominio de email del cliente y hacer una prueba real. Y probar por primera vez el envío de una plantilla de WhatsApp a Meta con las credenciales del cliente.", false],
  [8, "Dejar la infra de producción y el multi-cliente redondos", ["golive-encender-el", "multiinquilino-workspace"], 86, 25, "Cargar el secreto del webhook de Chatwoot en producción (sin él, se rechaza y la nutrición deja de pausarse cuando el lead contesta). Confirmar que todas las migraciones corrieron (un bug caro: si no corren, las inserciones fallan calladas). Y sacar los últimos cabos que asumen un solo cliente: reuniones de Fathom, emails internos y los recordatorios que deben salir al canal de cada cliente.", false],
  [9, "Los agujeros graves y medios ya tapados", ["cerrar-la-auditora"], 84, 100, "27 hallazgos verificados y cerrados. Se pasaron las consultas que filtraban datos entre clientes a la vía segura, el webhook de Chatwoot ahora rechaza lo que no viene firmado, y se cubrieron inyección de prompts, subida de avatares, accesos indebidos, protección contra pedidos falsos y límite de intentos de login.", false],
  [10, "Tapar las fugas entre clientes que quedan", ["cerrar-la-auditora", "multiinquilino-workspace"], 83, 0, "ANTES de traer clientes: el webhook de Chatwoot busca leads sin filtrar por cliente, el tracking del VSL y la landing va a la base sin acotar, y unas vistas de datos no tienen la columna de cliente. La regla que evita que esto vuelva: prohibir la conexión cruda a la base sobre las tablas de clientes fuera del único archivo autorizado.", false],
  [11, "Aplicar en producción lo que ya está resuelto en código", ["cerrar-la-auditora", "golive-encender-el"], 81, 0, "Cargar el secreto del webhook de Chatwoot en producción y pasárselo en la URL de Chatwoot (sin él, en producción se rechaza todo y la nutrición deja de pausarse cuando el lead contesta). Aplicar la migración de emails en minúsculas con sus índices. Y, opcional, forzar el origen del beacon de tracking.", false],
  [12, "Endurecer el navegador, evitar duplicados y sumar tests", ["cerrar-la-auditora"], 79, 20, "Falta endurecer la política de seguridad del navegador (hay que probarla ahí mismo), evitar que un webhook repetido dispare dos veces la misma acción, y tests que verifiquen que cada consulta queda de verdad acotada al cliente correcto. Ya hay tests de las reglas de etapa y del planificador.", false],
  [13, "Las 6 reglas del motor + el planificador (en simulación)", ["crm-automtico-leads"], 78, 100, "Las seis reglas que deciden cómo avanza un lead, la etapa de Reactivación y el planificador que arma el plan sin aplicarlo todavía. En la tab de Funnel hay una sección que explica en criollo qué mueve cada lead y por qué. Todo probado y sin el bug del bucle infinito.", false],
  [14, "Aplicar de verdad + red de confirmaciones + plantillas + hora exacta", ["crm-automtico-leads", "motor-de-nutricin"], 76, 100, "La parte que aplica cada movimiento con una red que evita repetir la misma acción sobre un lead, con deshacer quirúrgico y un aviso que no se puede cerrar hasta que confirmes. Pasó por una revisión durísima que dejó siete arreglos. Sumamos las plantillas de nutrición (no agenda, no-show, no paga, reactivación) y guardamos la HORA de cada reunión para que el chequeo de asistencia caiga a las 3 horas exactas.", false],
  [15, "Prenderlo por cliente + auto-completar datos + soltar el funnel fijo", ["crm-automtico-leads", "golive-encender-el", "ficha-del-lead"], 74, 15, "El interruptor del CRM automático es global: prenderlo mueve leads de todos. Hay que poder prenderlo en un piloto y mirar el primer lote real. Sumar una regla que autocompleta los 'datos sin marcar' leyendo el contrato con IA (la versión automática del asistente manual). Y soltar el funnel fijo: hoy el motor asume el embudo estándar, así que una etapa custom no dispara su nutrición.", false],
  [16, "Vista para espiar qué HARÍA el motor antes de prenderlo", ["crm-automtico-leads"], 73, 0, "Poder ver el plan que arma el motor en simulación sin esperar al chequeo automático, para auditar qué haría MaKo con cada lead y agarrar confianza antes de dar el interruptor.", false],
  [17, "Recordatorios de reunión propios (24h, 1h, 15 min)", ["recordatorios-de-juntas"], 72, 30, "Hoy los recordatorios los manda n8n a través de Chatwoot. Ya capturamos la hora de cada reunión desde Calendly; falta programarlos y mandarlos por nuestro propio canal (WhatsApp o email) y jubilar el workflow de n8n.", false],
  [18, "Follow-ups + el mensaje post-llamada que redacta MaKo", ["recordatorios-de-juntas", "motor-de-nutricin", "closing-analyst-analista", "mako-escribe-la"], 71, 0, "La tanda de follow-ups vive en n8n, apagada. Hay que rearmarla como secuencia dentro del motor de nutrición y prenderla. Y que apenas termina una llamada, MaKo redacte el follow-up usando el análisis de la llamada y la voz del cliente, con un borrador a un clic cuando el lead viene caliente.", false],
  [19, "Cobranza por WhatsApp que arranca desde los pagos", ["recordatorios-de-juntas", "motor-de-nutricin"], 71, 0, "La info de cobranza (vendido, cobrado, pendiente y el plan de cuotas) ya está cargada, pero nada dispara el seguimiento. Usar las cuotas como gatillo: cuota vencida arranca una secuencia de cobranza por WhatsApp que se corta sola cuando entra el pago.", false],
  [20, "Unificar las dos bases (la app piensa, n8n ejecuta)", ["recordatorios-de-juntas", "motor-de-nutricin"], 70, 0, "Hoy la app y n8n corren sobre dos bases de datos distintas que no se cruzan, y Calendly lo procesan las dos. La idea: que la app decida la nutrición con el funnel y el VSL, y que n8n solo ejecute lo que quede pendiente, o directamente lo apagamos.", false],
  [21, "Datos aislados por cliente, hasta con la caché", ["multiinquilino-workspace"], 69, 100, "Cada tabla ahora sabe a qué cliente pertenece, y hay una capa que resuelve de quién es cada pedido (usuario a su cuenta; agencia entrando como alguien vía una cookie firmada; sin definir, se corta por seguridad). Toda consulta queda filtrada al cliente correcto sola, incluso cuando pasa por la caché, que era justo donde se filtraban datos.", false],
  [22, "Panel de agencia + 'Entrar como' un cliente", ["multiinquilino-workspace"], 68, 100, "La agencia, sin entrar como nadie, ve su propio panel con las pestañas de Clientes (crear, pausar, renombrar) y Usuarios. El botón 'Entrar como' pone una cookie firmada y muestra un cartel de que estás impersonando.", false],
  [23, "Cada cliente con sus credenciales e ingesta en vivo", ["multiinquilino-workspace"], 67, 100, "Cada cliente usa su propio token para conectarse a los servicios, y las vistas en vivo se muestran solo si esa integración está conectada. La ingesta recorre todos los clientes activos aislando errores: si uno falla, no arrastra a los demás.", false],
  [24, "La Retro que lee todo el negocio y te arma el plan", ["retro-real-rendicin", "experimentos-como-fuente"], 66, 100, "MaKo recorre el negocio por áreas y la ejecución en vivo, te da veredictos y, cuando aceptás, crea de verdad los experimentos y las tareas (sin duplicar si repetís). Vive en tres pestañas: Retro, Experimentos y Conclusiones. Ya está en prod.", false],
  [25, "Que MaKo verifique lo que hiciste y te lo reclame", ["retro-real-rendicin", "board-plan-perro"], 65, 0, "El corazón del proyecto. Hoy la Retro mira si tocaste 'Aceptar', no si el experimento se ejecutó de verdad. Hay que cruzar lo aceptado con lo realmente hecho, reclamarte solo lo que quedó colgado y no volver a proponerte lo que ya ignoraste, con un chequeo barato que no queme plata.", false],
  [26, "Catálogo de fugas + objeciones que se repiten", ["retro-real-rendicin", "closing-analyst-analista"], 65, 0, "Que MaKo juzgue con criterio (dos señales, no una) los patrones típicos que queman plata: escalar lo que no gana, gasto que sube y resultados que bajan, poca variedad de creativos, huecos del funnel, cobranza que se repite. Y traer las objeciones que ya salen del análisis de llamadas y mostrarlas como patrón.", false],
  [27, "Una conclusión por pantalla, lista al abrir", ["retro-real-rendicin", "dashboard-de-analtica"], 64, 25, "En vez de correr la Retro entera cada vez (es cara, unos 13 minutos), precomputar una conclusión accionable por pantalla después de la ingesta diaria. Así cada tab abre ya con su veredicto y baja el costo. Los bloques de datos ya están al 80%.", false],
  [28, "Vista Hoy + un latido que te reclama", ["pulso-diario-vista", "comunicacin-con-el"], 63, 20, "Ya hay un bloque 'Hoy' embrionario con las juntas y la cola de acción. Falta el latido de verdad: un chequeo diario barato que lee qué se hizo, y si dejaste algo colgado te lo reclama por la campanita y por WhatsApp.", false],
  [29, "Semáforo que razona alertas, no que solo linkea", ["pulso-diario-vista", "dashboard-de-analtica"], 62, 0, "Hoy el semáforo son seis reglas fijas que terminan en un link, cero criterio. Que Claude mire las señales ya calculadas más la tendencia y arme alertas nuevas y accionables de un clic, con un pre-filtro barato para no gastar tokens de más.", false],
  [30, "Propuestas de MaKo cuando no estás en el chat + a quién llamar hoy", ["pulso-diario-vista", "tooluse-core-de", "comunicacin-con-el"], 61, 0, "Que MaKo te aparezca aunque no estés en el chat: aviso en la campanita, una bandeja de propuestas y una línea en el resumen diario por WhatsApp, nunca un pop-up que te frene para lo no urgente. Y un solo termómetro del lead (recencia de WhatsApp, clic de email, revisita al VSL, tono de la última llamada) que unifique las cuatro temperaturas que hoy se contradicen y ordene a quién llamar primero.", false],
  [31, "Briefing de la mañana + dónde está el cuello", ["pulso-diario-vista", "tooluse-core-de"], 60, 0, "Un briefing matutino con las 3 jugadas que más plata mueven, uno pre-llamada (VSL, Calendly y de dónde vino el lead en una sola pantalla) y un diagnóstico que te diga cuál es el cuello del funnel: la única palanca que hoy mueve la aguja. Todo colgado del cerebro de MaKo.", false],
  [32, "Editor de funnel + rediseño del proceso + Fathom (hecho)", ["funnel-como-fuente"], 59, 95, "El funnel se deriva solo desde una definición liviana: tipos de etapa, bandas, disparadores automáticos y manuales, plantillas VSL y Webinar. La nutrición positiva quedó como estado derivado, el No Show se marca por reunión (R1/R2/R3) y hay reuniones excepcionales. Fathom marca asistencia solo con las llamadas de VENTA, para no ensuciar el dato con las de servicio.", false],
  [33, "Que los tableros lean el funnel, no cuatro etapas fijas", ["funnel-como-fuente", "dashboard-de-analtica"], 59, 15, "Hoy las métricas del embudo están clavadas a cuatro etapas: si agregás una, los dashboards la ignoran y te mienten. Calcular tasa de cierre, distribución y limpieza desde tu funnel real y confirmar que sumar una etapa no rompe ningún tablero. Es la palanca número 2 del roadmap.", false],
  [34, "Que MaKo y la nutrición conozcan tus etapas reales", ["funnel-como-fuente", "tooluse-core-de", "motor-de-nutricin"], 58, 20, "MaKo hoy opina del proceso sin saber cuáles son tus etapas. Hay que inyectarle el funnel real (etapas, disparadores, bandas). Y hacer la nutrición agnóstica: hoy una etapa a medida no dispara su secuencia (las plantillas cubren solo los funnels comunes), así que hay que derivar la secuencia desde el funnel y enrolar al lead según su etapa.", false],
  [35, "SLAs por etapa + alerta cuando un lead se estanca", ["funnel-como-fuente"], 57, 0, "Poner un límite de días por etapa, un criterio de salida y un registro de cada cambio de etapa para medir cuánto tarda un lead en cada paso y avisarte cuando se pasa. Es la palanca 3; necesita que los tableros ya lean el funnel. Incluye guardar de dónde salió cada reunión: Calendly, Google/Fathom o fuera de Calendly.", false],
  [36, "Asistente para mover el lead + pestañas ordenadas", ["ficha-del-lead"], 56, 100, "El diálogo para mover el lead ahora es un asistente centrado, con el logo de MaKo, una pregunta por paso ('¿hubo primera reunión? ¿segunda?'), con motivo, con la parte de Fathom omitible y un 'Atrás' que funciona de verdad. Las excepciones quedan guardadas. Las pestañas se renombraron a resumen, tracking, reuniones, datos del trato e historial, y el selector de etapa va a dos columnas.", false],
  [37, "Datos del trato + cuotas + reuniones + tracking + chat", ["ficha-del-lead"], 55, 95, "La tarjeta de datos del trato (pagos, fiscales, servicio, promesa, obligaciones) con 'completar con IA leyendo el contrato' sin pisar lo cargado, y un solo botón de editar y guardar. Cuotas claras con aviso de si cuadran o no. Reuniones con las respuestas de Calendly por cada una. Tracking fino por persona a través de varias landings y VSLs. Y una pestaña de chat, con el contacto de WhatsApp asegurado en los tres puntos de alta.", false],
  [38, "Análisis de MaKo + reuniones automáticas + ficha única", ["ficha-del-lead"], 54, 95, "El análisis generativo del lead, con un candado por etapa, prompts editables y todo lo que viene de afuera tratado como no confiable (pasó una revisión de 18 agentes). La búsqueda automática de reuniones cruza Calendly, Fathom y Google Calendar y arranca en modo 'automático'. Y se fusionó todo en una ficha única: el modal solo muestra, la edición va por su ruta, y la ficha vieja se borró.", false],
  [39, "Datos sin marcar + Closer/Setter con foto + asistente Solucionar", ["ficha-del-lead", "cuentas-roles-y"], 53, 90, "'Datos sin marcar' como una sola fuente (tarjeta, badge rojo y botón Solucionar), el asistente que resuelve todo de una (trato, documentos y segunda reunión de Calendly), Closer y Setter con la foto del equipo y el closer detectado solo desde Fathom, y el deshacer completo del movimiento con historial que dice quién lo hizo.", false],
  [40, "Deuda: la timeline y el cierre atados a un funnel fijo", ["ficha-del-lead", "funnel-como-fuente"], 53, 10, "La línea de tiempo y las reglas de etapa dan por hecho el embudo estándar de dos reuniones e ignoran el funnel de cada cliente; para funnels custom (tres reuniones o más) hay que derivarlas. Y mover el cierre (monto y fecha) adentro de la sección de pagos con un solo botón de guardar: hoy el cierre se guarda por separado y arreglarlo es reescribir mucho, así que quedó diferido por riesgo.", false],
  [41, "Motor de nutrición por WhatsApp + reglas anti-baneo (hecho)", ["motor-de-nutricin", "bandejas-de-whatsapp"], 52, 100, "Motor que según la etapa del lead programa y dispara los mensajes, con reglas para no comerse un baneo y un candado de 20h por lead. Envío real por WhatsApp en horario laboral (9 a 17 MX). 28 plantillas para 13 etapas, sembradas solas por cliente, sin tocar nada a mano. El envío real vive detrás de un flag.", false],
  [42, "Email marketing sobre el mismo motor (Resend)", ["motor-de-nutricin"], 51, 100, "Las secuencias de email son pasos del mismo motor: comparten cohorte, ritmo de envío y candado con WhatsApp. Envío por Resend, campañas a un segmento, seguimiento de aperturas y clics, y baja automática. Ya funciona por cliente, con flags, dominio y envíos propios.", false],
  [43, "Redactar, aprobar y publicar plantillas de WhatsApp en Meta", ["motor-de-nutricin", "mako-escribe-la", "bandejas-de-whatsapp"], 50, 100, "Todo el circuito para mandar una plantilla a Meta: un validador de IA la corrige antes de enviarla, se publica, se sigue su estado y se puede editar la ya aprobada, con el motivo de rechazo real y un aviso del veredicto. Sin plantillas aprobadas no hay forma de reabrir la ventana de 24h.", false],
  [44, "Inbox oficial (Chatwoot): responder, multimedia, avisos (hecho)", ["bandejas-de-whatsapp"], 49, 100, "El chat de WhatsApp oficial dentro de la app: leer y responder, mandar fotos, audio, video y archivos, notas de voz, emojis, ver el estado del mensaje, respetar la ventana de 24h, borradores y bloqueo con motivo. Los avisos de mensaje nuevo se detectan por la dirección del mensaje (el contador de no leídos siempre viene en cero) y la ficha del lead se abre a un clic.", false],
  [45, "Canal no oficial por QR: el número real de venta (hecho)", ["bandejas-de-whatsapp", "infraestructura-propia-e"], 48, 100, "El segundo canal: el número real de venta del cliente conectado por QR, sin las restricciones de la API oficial. Conexión, espejo del historial que no rompe nada, media a un espacio privado, envío con demora anti-baneo, borradores, lectura en vivo, agrupado por teléfono y avisos. Paridad total con el canal oficial.", false],
  [46, "Al entrar a WhatsApp, MaKo te arma toda la nutrición", ["bandejas-de-whatsapp", "arranque-del-cliente", "mako-escribe-la"], 48, 0, "La primera vez que entrás (nada conectado, sin plantillas), un arranque que le pide a MaKo generar la nutrición de todas las etapas; vos solo aprobás y conectás. Tiene que registrar Y verificar el webhook, para no repetir el fallo silencioso que tuvimos con el espejo. Baja la fricción del arranque a casi cero.", false],
  [47, "Cerrar el canal no oficial: tildes, bloqueo, abrir desde el CRM", ["bandejas-de-whatsapp", "ficha-del-lead"], 47, 25, "Falta bloquear un contacto o teléfono, un componente de tildes compartido (los dobles ✓✓ todavía no se pintan del todo), abrir el chat directo desde la ficha del lead, y endurecer: un token propio por número, saber quién mandó cada mensaje manual y el flujo para reengancharse tras un baneo (chip nuevo + QR + el historial ya espejado).", false],
  [48, "Biblioteca de copywriting que hace mejor a MaKo", ["mako-escribe-la", "sistema-de-contexto"], 47, 90, "MaKo escribe apoyado en una metodología curada (AIDA/PAS/BAB, gatillos emocionales, cómo se arma una secuencia que convierte) más un archivo de ejemplos reales que funcionan (swipe) para copiar el tono. Eso levanta la calidad del generador, del asesor de WhatsApp y de las plantillas. Falta cargar más ejemplos ganadores.", false],
  [49, "Aprender la voz → escribir la secuencia → mandarla a Meta", ["mako-escribe-la", "motor-de-nutricin", "bandejas-de-whatsapp"], 46, 100, "MaKo estudia los anuncios del negocio y arma una guía de su voz; después reescribe solo el texto de cada paso (los tiempos y la estructura quedan igual) y vos aprobás. Con un clic ese mensaje se convierte en plantilla de WhatsApp lista para aprobar en Meta, y elegís por paso si sale por el número oficial o por el no oficial.", false],
  [50, "Estudio de copy para anuncios", ["mako-escribe-la", "agente-de-ads"], 45, 100, "MaKo escribe el copy de los anuncios de Meta apoyado en la misma biblioteca de copywriting y en el perfil del negocio. Cubre el 'escritor fantasma' que estaba en el roadmap.", false],
  [51, "Escritor de VSL + escritor de DMs + loop analizar→escribir→producir", ["mako-escribe-la", "script-analyst-analista", "landing-de-venta"], 45, 0, "Hoy las pantallas de escritor de VSL y de DMs son solo un cartel de 'próximamente'. Falta el generador de guiones de VSL y el de DMs con el mismo patrón. Y el diferencial grande: encadenar Script Analyst (detecta qué mejorar del guion) → escritor de anuncios (lo reescribe) → generador del creativo, todo de una pasada. Lejano.", false],
  [52, "Wizard de arranque + extracción del histórico en vivo (hecho)", ["arranque-del-cliente", "cimientos-de-datos"], 44, 100, "El cliente nuevo pasa un wizard que no lo deja salir hasta conectar. Al verificar Meta arranca la extracción de su histórico con un panel en vivo, reanudable aunque cierre la pestaña, y sin que dos procesos pisen lo mismo. También configura tabs, su negocio y la primera Retro, todo con el control del lado del servidor.", false],
  [53, "Vista simple por default, kanban para el que quiere más", ["arranque-del-cliente", "board-plan-perro"], 44, 0, "Que el cliente vea por default 3 tareas curadas más experimentos, y el kanban completo quede detrás de un toggle 'Avanzado' que se recuerda por cliente. Hoy no existe la vista simple. Es el norte del producto: que la app te diga qué hacer, no que te abrume.", false],
  [54, "Mini-onboarding al abrir cada tab (sacarlos del wizard)", ["arranque-del-cliente"], 43, 30, "Que cada pantalla te guíe la primera vez que la abrís (el email ya lo hace con el dominio) y sacar del wizard grande lo que puede esperar: email, Fathom, VSL y Calendly. Solo Meta y WhatsApp quedan en el arranque obligatorio, así el primer contacto es más liviano.", false],
  [55, "Extracción que sigue de noche + plantillas por rubro", ["arranque-del-cliente", "cimientos-de-datos", "motor-de-nutricin"], 42, 25, "Hoy el histórico solo avanza con la pestaña abierta: falta que corra de noche solo. Y terminar la idea de 'menos config': el editor de funnel ya es liviano; falta un banco de plantillas de nutrición por tipo de negocio y resaltar lo que el usuario suele saltear.", false],
  [56, "Armador de campañas nuevas con MaKo", ["cerrar-el-ciclo", "rplica-de-meta"], 42, 100, "Lanzar una campaña con una pregunta por pantalla: creativos, inversión, objetivo, estrategia, público y destino. Con eso MaKo propone la estructura y escribe el copy; vos revisás y publicás en pausa. Lo que decidís vos manda, MaKo solo redacta. Crea la campaña, el conjunto, el anuncio y el creativo, sube los videos e imágenes y soporta Instagram y Threads. El selector de conversión muestra primero el pixel y solo los eventos que están activos.", false],
  [57, "Salud de la cuenta de Meta + recomendaciones", ["cerrar-el-ciclo", "pulso-diario-vista"], 41, 50, "Una vista que responde '¿la cuenta está entregando?': estado de pago, resumen de entrega y botón para que MaKo la analice, más una alerta roja en el semáforo si la cuenta está impaga, deshabilitada o con problemas. Meta bloquea sus recomendaciones nativas por el tema de pago, así que las deriva MaKo. Ya está el análisis a pedido y el historial de estados malos; falta que las recomendaciones salgan solas y sean accionables.", false],
  [58, "Avisarle a Meta cuándo cobrás (Purchase por CAPI)", ["cerrar-el-ciclo", "dashboard-de-analtica"], 41, 60, "Los eventos de arriba del embudo (lead, lead calificado y agenda) ya se le mandan a Meta por la Conversions API cada vez que se actualiza un lead, venga del webhook, de Fathom o de la carga manual. Falta el evento Purchase al cobrar (cierre o cuota) con el monto real, para que Meta optimice sobre la plata que entra y no solo sobre las agendas. Con control de duplicados y verificado en el panel de eventos de Meta.", false],
  [59, "Confirmar en vivo que Meta deja crear + pendientes menores", ["cerrar-el-ciclo", "rplica-de-meta"], 40, 0, "Riesgo abierto: que MaKo pueda pausar, cambiar presupuesto y renombrar NO garantiza que Meta le deje crear campañas nuevas; ese permiso hay que confirmarlo contra la cuenta real recién al publicar (no se pudo probar la creación de verdad desde el entorno de pruebas). Menores: armar formularios de lead ads desde cero (hoy solo reusa los que ya existen), no duplicar si se reintenta, y manejar videos pesados que tardan en subir.", false],
  [60, "Navegador estilo Meta + escribir estado/presupuesto/nombre", ["rplica-de-meta", "agente-de-ads"], 39, 100, "Tabla ordenable con multiselección, columnas configurables, primera columna fija, encender/apagar y presupuesto editables en la misma fila, estado en vivo + señales + datos del CRM, y detalle por entidad con gráficos. Los cambios llegan a Meta revisando el error real que a veces viene dentro de una respuesta OK, se aplican al instante y se revierten si fallan, solo para el dueño.", false],
  [61, "Renombrar en lote por plantilla + edición en la fila", ["rplica-de-meta"], 39, 100, "Editar el nombre en la misma fila y renombrar en lote con MaKo por PLANTILLA con variables: MaKo solo devuelve las partes con sentido (objetivo, ángulo, etc.) y el nombre se arma con la plantilla. Numeración jerárquica anclada al padre (001 / 001.01 / 001.01.a), mes y año consistentes, y filtro por rango de fecha. Verificado 26 de 26.", false],
  [62, "Editar público / +anuncio / +conjunto + resumen de problemas", ["rplica-de-meta", "cerrar-el-ciclo"], 38, 100, "Los tres cambios por fila (todo en PAUSA): editar el público de un conjunto superponiendo solo lo que tocás (porque Meta reemplaza todo el público si no), agregar un anuncio y agregar un conjunto que hereda del primero. Un anuncio 'con problemas' propaga el aviso hacia su conjunto y su campaña, con un chip clickeable en español y opción de editar los textos. Presupuesto mostrado en dólares.", false],
  [63, "Armado del contexto + conocimiento recuperado + fases + arranque (hecho)", ["sistema-de-contexto", "tooluse-core-de"], 38, 100, "MaKo combina persona + núcleo + perfil + instrucción de la pantalla + conocimiento + datos, y si algo falta usa el prompt de antes sin romperse. El conocimiento se guarda listo para buscar por similitud y se re-indexa solo cuando cambia. Fases por pantalla + wizard de arranque (Oferta/Avatar/Personaje) que extrae los datos con IA.", false],
  [64, "Prompts editables + conocimiento por cursos + asesor (hecho)", ["sistema-de-contexto", "bandejas-de-whatsapp"], 37, 100, "Registro central de prompts + guardado de ediciones con historial (30 versiones); pantalla de Configuraciones con los 33 prompts en 10 grupos, con guardar/restaurar/resetear y aviso en los delicados. El conocimiento se organiza por curso/autor/área; semilla del curso 'Levanta Muertos', alta manual y transcripción de audio. El asesor de WhatsApp ya usa esa metodología.", false],
  [65, "Registrar los prompts de Experimentos/Retro + corregir un cartel", ["sistema-de-contexto", "experimentos-como-fuente", "retro-real-rendicin"], 36, 25, "Los prompts de Experimentos y Retro se usan pero no están en la pantalla editable, así que no se pueden retocar sin redeploy: sumarlos al registro. Y en la vista de Contexto el núcleo figura como 'no editable' cuando desde Configuraciones ya sí lo es: corregir el cartel.", false],
  [66, "Mejorar la búsqueda de conocimiento + curar más cursos", ["sistema-de-contexto", "mako-escribe-la"], 36, 15, "A escala conviene una búsqueda de similitud nativa en la base (pgvector con índices) en vez de traer todo y comparar en memoria. Y activar el área 'ads' para que el conocimiento por área alimente también la generación de creativos, no solo los mensajes; curar y sembrar más cursos. Lejano.", false],
  [67, "Motor de hipótesis medibles + la regla en el núcleo + 3 vistas (hecho)", ["experimentos-como-fuente", "sistema-de-contexto", "retro-real-rendicin"], 35, 100, "Convierte una hipótesis en experimento con línea de base comparable, mide en vivo y da veredicto (validada/refutada/no concluyente) más el aprendizaje; es el único punto donde MaKo concluye. La regla 'hipótesis, no verdades' vive en el núcleo, y al contexto de MaKo solo entran las verdades validadas. Tres vistas (Retro/Experimentos/Conclusiones) con wizard y tarjetas en vivo.", false],
  [68, "Cerrar experimentos solos + destrabar las ideas", ["experimentos-como-fuente"], 34, 25, "La función de cierre ya existe y es segura porque la medición es automática, pero falta el proceso que cierre los experimentos solo al vencer. Además quedó suelto el generador de ideas de experimentos, sin nadie que lo consuma, y los estados propuesto/descartado están muertos en la pantalla.", false],
  [69, "Plata cobrada por anuncio + histórico de veredictos", ["experimentos-como-fuente", "cerrar-el-ciclo", "dashboard-de-analtica", "retro-real-rendicin"], 34, 0, "Cruzar cada anuncio con los pagos para tener el retorno real por creativo; hoy solo hay retorno agregado y tanto la Retro como el semáforo razonan sobre proxies (leads). Y guardar la serie de veredictos por anuncio (cuándo se valida uno, cuándo se apaga por quemar plata) que hoy se calcula pero no se persiste, para alimentar los detectores de 'quema de dinero'.", false],
  [70, "Motor venta vs servicio + análisis profundo (hecho)", ["closing-analyst-analista"], 33, 100, "Trae y pagina las llamadas de Fathom, matchea por el email del invitado externo, clasifica cada una (venta / entrega de servicio / interna / prueba) y puntúa solo las de venta, guardando fortalezas, debilidades, objeciones, próximo paso y momentos con su cita y su minuto. La grabación queda embebida con salto directo a cada momento.", false],
  [71, "Puntaje confiable + dos vistas + R1/R2 solo con ventas", ["closing-analyst-analista", "ficha-del-lead"], 33, 100, "Se arregló el falso puntaje 0: reintenta ante errores de Fathom, la venta sin transcript queda 'pendiente' (no cuenta como 0) y los promedios la excluyen. Vista de Métricas (KPIs, hallazgo de la semana, tendencia, embudo) y vista de Llamadas. Las reuniones que se auto-vinculan al lead usan SOLO las de venta; un script limpió 14 mal vinculadas y re-vinculó 50.", false],
  [72, "Perfil + campanita + motor de reportes", ["comunicacin-con-el"], 32, 100, "El perfil con sus pestañas y la config de por dónde querés recibir cada reporte, la campanita de avisos dentro de la app, y el motor que arma reportes por hora, día y semana y los manda por WhatsApp, email o Telegram. Incluye el truco para meterse en la ventana de 24h de WhatsApp: primero una plantilla de apertura y después el texto libre.", false],
  [73, "Reportes por cada cliente + soltar Telegram", ["comunicacin-con-el", "multiinquilino-workspace"], 31, 0, "Hoy los reportes y los envíos masivos de email salen solo para el dueño de la agencia, y Telegram está clavado a Mauricio. Que cada cliente reciba sus propios reportes, por su canal y su contacto.", false],
  [74, "MaKo responde y ejecuta lo que le pedís por WhatsApp", ["comunicacin-con-el", "bandejas-de-whatsapp"], 31, 10, "Mandarle reportes al dueño ya funciona; falta el camino de vuelta: que MaKo lea lo que el dueño le contesta y ante un 'sí, dale' pause las campañas de verdad y adjunte el PDF. Para eso el sistema tiene que distinguir si el mensaje que entra es del dueño o de un lead (hoy no lo diferencia y eso rompe el ruteo). Lo toca también el otro Claude: hay que coordinar.", false],
  [75, "Señales de WhatsApp en el lead + toques por lead", ["comunicacin-con-el", "ficha-del-lead"], 30, 20, "Guardar en cada lead cuándo respondió por última vez y su último mensaje: eso habilita el seguimiento automático del que no contesta, los tiempos límite y ordenar a quién atender primero. Sumar toques de nutrición individuales, editables desde la ficha. Y mostrar en el chat con qué número del cliente se contactó al lead (la pestaña de teléfonos ya está; falta cruzar la conversación con el número).", false],
  [76, "Cuentas reales con rol + login con Google (hecho)", ["cuentas-roles-y", "cerrar-la-auditora"], 30, 100, "Se reemplazó la contraseña compartida por cuentas de verdad: cada persona entra con su Google, con rol y estado (invitado, activo o suspendido), sesión firmada y credenciales cifradas. En cada pedido el sistema revisa contra la base quién es y si sigue habilitado.", false],
  [77, "Cargar los tokens de cada integración con tutorial (hecho)", ["cuentas-roles-y"], 29, 100, "Un asistente para el admin donde cada servicio tiene su paso a paso para conseguir el token, un botón para probar la conexión y guardado cifrado. Al arrancar, la app hidrata las credenciales; lo que esté cargado en Vercel siempre manda.", false],
  [78, "Roles por cliente (admin/closer/setter) + alta en un paso", ["cuentas-roles-y", "multiinquilino-workspace"], 28, 100, "Cada cliente tiene sus roles: admin-cliente, closer y setter, y cada uno ve solo sus pantallas. Dar de alta un cliente crea su workspace y su admin de una; desde /equipo se invita a closers y setters. El control es real del lado del servidor, no solo esconder botones del menú.", false],
  [79, "Vista General 'tu norte' + bloque Hoy", ["dashboard-de-analtica", "pulso-diario-vista"], 28, 100, "El objetivo global con su ritmo y su fecha estimada de llegada como lo primero que ves, un bloque 'Hoy' con las juntas del día y la cola de acción, la inversión por anuncio, y que desde cualquier total puedas bajar hasta los nombres de los leads. Es la pantalla que contesta '¿voy bien?' de un vistazo.", false],
  [80, "Marketing: CAC/ROAS + tendencias + anuncios ganadores", ["dashboard-de-analtica", "agente-de-ads"], 27, 100, "CAC como número grande global, semanal y mensual, ROAS, resumen de la cuenta, tendencias en un gráfico grande con selector de métrica y varias series, y los anuncios ganadores (top 5 + ranking) con veredicto claro: validar si ya trajo 10+ leads, apagar si quemó 80 dólares sin ninguno. Con preview del creativo.", false],
  [81, "Comercial + Plata/Cobranza", ["dashboard-de-analtica"], 27, 100, "Comercial con cohortes, el ciclo de venta por tramos con su línea de tiempo, el no-show por cohorte e ingresos contra gasto. Plata con vendido/cobrado/por cobrar (mirando hacia adelante por fecha de vencimiento), plan de pagos en cuotas, el contrato firmado leído por IA que autocompleta el plan, y 'a quién cobrarle' con marcar cobrado y deshacer.", false],
  [82, "Cada número clickeable → desglose por lead + filtro de fecha + mobile", ["dashboard-de-analtica"], 26, 100, "El patrón en toda la app: tocás un número y se abre el desglose con los leads que lo componen (cohortes, tramos, vendido/cobrado). Un filtro de fecha global que se mantiene mientras navegás, todas las fechas en formato día/mes/año, y la app usable en el celular. Es lo que hace el tablero auditable hasta el nombre.", false],
  [83, "Conector de Meta Ads (rendimiento + presupuestos + histórico)", ["cimientos-de-datos"], 24, 100, "Meta a nivel de cada anuncio, los presupuestos diarios de los conjuntos de anuncios, la carga del histórico completo de rendimiento y un repaso diario de leads como red de seguridad. Es la columna vertebral del gasto y la performance.", false],
  [84, "Agendas y formularios que entran solos (Calendly + Meta)", ["cimientos-de-datos"], 23, 100, "El webhook de Calendly que da de alta el lead solo, con sus UTMs y las cuatro respuestas del formulario; la carga del histórico de Calendly como leads; y el webhook de Meta Lead Ads cruzando por teléfono. Cierra la captura de agendas y formularios desde las dos puntas.", false],
  [85, "CAPI: devolverle a Meta las conversiones de arriba del embudo", ["cimientos-de-datos", "cerrar-el-ciclo"], 23, 100, "La base para mandarle a Meta los eventos de conversión (Lead, Lead Calificado y Agenda) por su API de conversiones, para que optimice mejor las campañas. El evento de Compra al cobrar queda pendiente y vive en el proyecto de cerrar el ciclo con Meta.", false],
  [86, "Las fuentes del VSL: YouTube + Panda", ["cimientos-de-datos"], 22, 100, "YouTube por su API de analítica (no acumulado), una serie continua que incluye el VSL anterior, y Panda como fuente del VSL actual con su tarjeta en Marketing. Habilita las curvas de retención y la etapa VSL del embudo.", false],
  [87, "Separar lo estable de lo vivo + Patrones + Cuadrante (hecho)", ["script-analyst-analista", "rplica-de-meta"], 21, 100, "La lectura del guion se guarda sin métricas, así no envejece; las métricas se agregan por anuncio sin filtro de fecha (gasto, hook rate, retención por tramos, agendas, cierres, veredicto). Los Patrones se calculan con umbrales y el Cuadrante quedó calibrado con ejes y umbrales fijos.", false],
  [88, "Valorar un guion nuevo + taxonomía + imágenes + detalle unificado", ["script-analyst-analista", "rplica-de-meta"], 21, 100, "Pegás un guion nuevo y MaKo lo compara contra el perfil de la cuenta: lo clasifica, dice qué patrones cumple y cuáles pierde, predice el veredicto y propone reescrituras, guardando el historial. Taxonomía de ángulos/avatares editable compartida con el arranque + override por anuncio. Imágenes leídas por OCR. Detalle unificado (Rendimiento/Audiencia/Guion) reusado por el Ads Manager.", false],
  [89, "Limpiar código muerto + tablero por veredicto", ["script-analyst-analista"], 20, 0, "Borrar dos componentes viejos que quedaron huérfanos: el administrador de ángulos anterior y un navegador de anuncios que ya no se usa. Y una idea pendiente: un tablero tipo kanban, alternativo al cuadrante, agrupado por veredicto (Escalar / Reescribir / Mejorar / Repensar).", false],
  [90, "Rebuild a /plan (Trello) + Perro Guardián", ["board-plan-perro"], 19, 100, "Tablero tipo Trello que se adapta al rol: columnas de prioridad, arrastrar y soltar, checklists que derivan el avance, proyectos editables, filtros, deshacer, confirmaciones e historial de cambios, con un mismo componente para agencia y cliente. El Perro Guardián prioriza, propone re-priorizar, fija un objetivo principal, debate cada tarea, cuida la pirámide y ordena los proyectos del 1 al 10 sin empates.", false],
  [91, "Sacar tareas de reuniones + poblar el tablero (hecho)", ["board-plan-perro", "closing-analyst-analista"], 19, 100, "Extraer tareas del plan directamente desde una reunión de Fathom. Proyectos y tareas de arranque para clientes nuevos (tablero 'Ambos' con las que ya hizo Mauricio). Poblado con todo el roadmap sacado de la memoria (123 tareas).", false],
  [92, "Cerrar pendientes de desarrollo del tablero", ["board-plan-perro"], 18, 10, "Sacar el modo de prueba que permite saltearse el debate del Perro Guardián, cuando se cierre el desarrollo. Guardar de verdad el motivo del puntaje y el deadline del tablero del cliente (hoy viven solo en memoria, falta migración). Y que la extracción desde Fathom use la cuenta de cada cliente en vez de la de la agencia.", false],
  [93, "Tablero con look nuevo + sidebar plegable", ["reskin-de-la"], 18, 80, "El tablero de marketing pasado al tema claro en sus 8 pantallas con la interactividad de vuelta, alineado al look de la landing, con el ícono propio de la app y las pantallas portadas del diseño (funnel, closing, Retro). El sidebar se pliega a un riel que se abre al pasar el mouse, con los grupos y el perfil en menús laterales. Falta cerrar los analistas, experimentos, el perfil y el onboarding.", false],
  [94, "Identidad MaKo (logo, voz, análisis en cada gráfico)", ["reskin-de-la"], 17, 80, "El logo y la marca de MaKo, la voz rioplatense y el modelo de IA que ajusta el esfuerzo según la tarea. Cada gráfico lleva al lado un análisis de MaKo con su propio historial y sus sesiones. Falta ponerle ese ✦ a los gráficos que todavía no lo tienen y borrar el logo viejo que quedó dando vueltas.", false],
  [95, "Desplegables propios + textos R1/R2 + admin de eventos", ["reskin-de-la"], 16, 50, "Usar el desplegable propio en toda la app, nunca el nativo pelado; quedan un par de pantallas viejas por migrar. Los nombres de reuniones ya están casi todos como R1/R2; faltan dos lugares, y ahí se cambia solo el texto que se ve, nunca las claves internas. Y un administrador de eventos que no arrancó.", false],
  [96, "Landing /vsl + realce del CTA", ["landing-de-venta"], 16, 100, "La landing armada desde el diseño (no HTML a mano) con toda su interactividad de vuelta: carruseles, video, Calendly embebido, animaciones. Responsive para celular y el CTA reforzado con escasez honesta, la oferta y micro-señales de confianza, todo sin tocar el diseño original.", false],
  [97, "Identificar al espectador anónimo del VSL", ["landing-de-venta", "cimientos-de-datos"], 15, 100, "Tres caminos para convertir un ID anónimo en un lead con nombre: el directo (viene con el ID del lead en el link y queda estampado al instante) y dos por Calendly. Todo el comportamiento fino del VSL (cuánto retiene, cuántos VSL vio) queda colgado de ese ID. El grabado anónimo funciona bien; el cuello es el bautismo, o sea ponerle nombre al anónimo.", false],
  [98, "Pegar el código en la landing + flujo de WhatsApp (depende de Martín)", ["landing-de-venta"], 14, 0, "El instructivo está listo: sumarle al seguimiento la URL y el título del VSL, y leer el ID del lead en todos los eventos. Falta que Martín lo pegue en la landing con el dominio real y arme el flujo de WhatsApp que mande el link con el ID del lead, que es por donde entra el grueso del tráfico y cierra el camino directo.", false],
  [99, "15 páginas de detalle + completar los huecos", ["landing-de-venta"], 14, 40, "Las 15 páginas de detalle por funcionalidad (con sus testimonios), públicas, con el estilo de VSL y los links 'Saber más' inyectados. Faltan las capturas y demos de cada una, llenar los testimonios, y que las tarjetas del grid de arriba lleven a la página de detalle en vez de a un ancla. El contenido lo completa Martín.", false],
  [100, "Mapa navegable del código (Graphify)", ["skills-de-claude"], 13, 100, "Después de probar que una opción no servía para este código, Graphify sí: arma un mapa de quién llama a qué a lo largo de todo el proyecto (miles de conexiones, con archivo y línea). Subido con su receta, la regla en la documentación del repo y un visor dentro del panel de super-admin.", false],
  [101, "11 recetas del repo + públicas seleccionadas", ["skills-de-claude"], 12, 100, "Once recetas a medida del código: cuatro base (consultas seguras por cliente, migraciones numeradas, convenciones de la app, prompts editables) y siete que tapan huecos concretos (auditar fugas entre clientes, armar tareas programadas, conectar servicios nuevos, recibir webhooks, chequear prompts, y armar analistas y writers de MaKo). Más algunas públicas elegidas sin pisar las que ya vienen de fábrica.", false],
  [102, "Gasto de IA por operación + saldo a mano", ["skills-de-claude"], 12, 100, "Registro de cuántos tokens y cuánta plata gasta cada operación de IA por modelo, y un chip 'Saldo IA' en el sidebar que muestra lo que queda (saldo cargado menos gasto, porque la API de Anthropic no da el saldo prepago), el gasto de cada operación al instante y el historial con el motivo en criollo.", false],
  [103, "Usar las recetas como hábito", ["skills-de-claude"], 11, 25, "Las recetas están instaladas pero falta usarlas siempre al construir (evitar fugas entre clientes, numerar bien las migraciones, no dejar prompts desincronizados) y volverlo un hábito documentado. Incluye chequear de forma sistemática que cada migración subida esté realmente aplicada en producción, algo que ya falló caro una vez.", false],
  [104, "Guardar el histórico de veredictos por anuncio", ["agente-de-ads", "dashboard-de-analtica"], 10, 20, "Hoy el veredicto de cada anuncio (validar o apagar) se calcula al vuelo y no se guarda, así que no hay forma de detectar 'lleva N días quemando plata'. Guardar una foto diaria destraba los detectores de quema en el tiempo.", false],
  [105, "Reglas de presupuesto según la plata real", ["agente-de-ads", "cerrar-el-ciclo"], 10, 0, "Subirle a los que venden y recortarle a los que no, según la plata cobrada atribuida a cada anuncio (el cruce de gasto × leads × pagos), no solo por cuántos leads trajo. Incluye duplicar el ganador. Es la apuesta central una vez que la plata por anuncio está calculada.", false],
  [106, "Ejecutar con tu OK + rastro", ["agente-de-ads", "rplica-de-meta"], 9, 10, "Proponer cada cambio de presupuesto o estado y aplicarlo recién con tu confirmación, dejando rastro de quién lo hizo y por qué. La IA propone, vos decidís, y queda registrado.", false],
  [107, "Analizar las llamadas de entrega en vez de tirarlas", ["cs-analyst-analista", "closing-analyst-analista"], 8, 0, "Hoy las llamadas de entrega del servicio se transcriben y se descartan. Correrles el mismo analista que usamos para las de venta (resumen, riesgos, próximos pasos) y cargar el histórico ya transcripto. El costo extra es casi cero porque la transcripción ya se hace igual.", false],
  [108, "Termómetro de baja por cliente", ["cs-analyst-analista"], 8, 0, "Un termómetro por cada cliente activo que combina el ánimo de su última llamada de servicio con la cuota impaga y otras señales, para ordenar a quién retener primero. Cálculo directo donde se pueda, IA solo para leer el ánimo.", false],
  [109, "Vista de cartera + alertas de baja al dueño", ["cs-analyst-analista", "comunicacin-con-el"], 7, 0, "Una vista de la cartera con semáforo de riesgo y alertas de baja que le llegan al dueño por campanita o WhatsApp con la acción sugerida. Cierra el loop: no solo detecta, avisa y propone qué hacer.", false],
  [110, "Oferta por niveles + un anuncio por funcionalidad", ["growth-vender-mako", "landing-de-venta"], 7, 0, "Venderle a todo el que corra un VSL Funnel, con planes por nivel que desbloquean según la situación del cliente (definir los niveles y qué abre cada uno). Modelo Claudio Conde (vender caro con una sola funcionalidad): producir muchos anuncios, cada uno vendiendo una sola cosa que hace MaKo.", false],
  [111, "Página de gracias + testimonios + demos + costos", ["growth-vender-mako", "landing-de-venta"], 6, 0, "La página post-agenda que obliga a preparar la llamada o la cancela, juntar y mostrar testimonios reales, un Loom de demo por funcionalidad, y sumar a la landing tarjetas de funcionalidades que ya existen pero no figuran (revenue y cobranza, vista general, contrato leído por IA, pendientes). Más el costo interno y por cliente y un mapa de uso. Para cuando vuelva a Buenos Aires.", false],
  [112, "Cuentas propias por cliente + plan pago", ["infraestructura-propia-e", "multiinquilino-workspace"], 5, 20, "La cuenta gratis de email da 3.000 por mes y 100 por día, y con una sola cuenta para todos los clientes eso se topa rápido: al escalar hace falta el plan pago y una cuenta propia por cliente para el email y el WhatsApp no oficial (la puerta ya está prevista en las credenciales). Habilita el volumen sin chocar con los límites de envío.", false],
  [113, "Pasar cuentas a nombre propio + dominio + método de actualización", ["infraestructura-propia-e", "landing-de-venta"], 5, 0, "Mover la base de datos, el hosting y el dominio de Mauricio a cuentas propias y servir la landing desde la raíz de un dominio propio. Definir cómo ir mejorando sin cortarle a los que están probando (activar cosas por cliente, un registro de cambios, probar antes de exponer); hoy todo va directo a producción. No es prioridad hasta que haya clientes pagando.", false],
  [114, "Bot que contiene el tráfico frío + que el lead escriba primero", ["canales-fros-bot", "bandejas-de-whatsapp"], 4, 0, "El tercer número del esquema: un bot en la línea oficial que recibe a la gente que llega fría desde los ads, la califica con plantillas y la pasa al número de venta ya tibia. Sumado al patrón de que escriba primero (links de WhatsApp con palabra clave y QR en vivo), que baja el riesgo de baneo alrededor del 90%.", false],
  [115, "Instagram y mail del lead en la bandeja única", ["canales-fros-bot", "bandejas-de-whatsapp"], 3, 0, "Instagram hoy es una pantalla vacía de 'próximamente': traer los DMs de IG a la bandeja unificada. Y un buzón de mail por lead: hoy el mail sirve solo para nutrición y envíos masivos, y el botón de la ficha abre el cliente de correo. Falta ver la conversación y el historial de mails dentro de la ficha.", false],
  [116, "Investigar la transcripción en vivo", ["copiloto-en-vivo"], 3, 0, "Evaluar proveedores de transcripción en tiempo real, medir la demora real y el costo por llamada, y ver si es viable montarlo sobre lo que ya tenemos sin arruinar la experiencia del closer.", false],
  [117, "Sugerencias al closer en tiempo real", ["copiloto-en-vivo", "closing-analyst-analista"], 2, 0, "Detectar las objeciones mientras pasan y sugerir cómo manejarlas desde el cerebro de closing y copywriting, en una interfaz discreta que no distraiga al closer durante la reunión.", false],
];

